import 'package:flutter/material.dart';
import 'package:file_picker/file_picker.dart';
import '../services/api.dart';
import '../widgets/figma.dart';
class MaterialsScreen extends StatefulWidget{final Map<String,dynamic> teacher; const MaterialsScreen({super.key, required this.teacher}); @override State<MaterialsScreen> createState()=>_MaterialsScreenState();}
class _MaterialsScreenState extends State<MaterialsScreen>{final api=const LarniaApi(); List<dynamic> items=[]; @override void initState(){super.initState(); load();} Future<void> load()async{items=await api.list('/api/materials?teacherId=${widget.teacher['id']}'); if(mounted)setState((){});} Future<void> addUrl()async{final c=TextEditingController(); final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Pridať webový odkaz',style:TextStyle(color:blue)), content:TextField(controller:c, decoration: const InputDecoration(hintText:'https://priklad.sk/clanok-na-studium')), actions:[FigmaButton(text:'Zrušiť',color:blue2,width:120,onPressed:()=>Navigator.pop(context,false)),FigmaButton(text:'+ Pridať URL',width:180,onPressed:()=>Navigator.pop(context,true))])); if(ok==true){await api.post('/api/materials/url', {'title':c.text,'url':c.text,'teacherId':widget.teacher['id']}); await load();}}
Future<void> addFile()async{final r=await FilePicker.platform.pickFiles(type:FileType.custom, allowedExtensions:['pdf','docx','txt'], withData:true); if(r==null)return; final f=r.files.single; if((f.size) > 10*1024*1024){showErr('Súbor je príliš veľký. Maximálna povolená veľkosť je 10 MB.'); return;} try{await api.uploadMaterial(name:f.name, bytes:f.bytes!, teacherId:widget.teacher['id']); await load();}catch(e){showErr(e.toString().replaceFirst('Exception: ',''));}} void showErr(String m)=>showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Pridať súbor',style:TextStyle(color:blue)), content:Text(m,style:const TextStyle(color:errorRed,fontWeight:FontWeight.w600)), actions:[FigmaButton(text:'Zrušiť',color:blue2,width:120,onPressed:()=>Navigator.pop(context))]));
@override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.white, body:Padding(padding: const EdgeInsets.fromLTRB(45,80,45,80), child:Column(crossAxisAlignment:CrossAxisAlignment.start, children:[const LarniaHeader(title:'Knižnica materiálov', subtitle:'Správa dokumentov a zdrojov pre AI učiteľa.'), const SizedBox(height:17), Row(children:[FigmaButton(text:'Pridať URL',color:blue2,onPressed:addUrl), const SizedBox(width:16), FigmaButton(text:'Nahrať súbor',onPressed:addFile)]), const Spacer(), items.isEmpty ? Container(width:932,height:245, alignment:Alignment.center, decoration:BoxDecoration(color:const Color(0xFFEBF9FA),borderRadius:BorderRadius.circular(20), border:Border.all(color:cyan,width:4), boxShadow: const [BoxShadow(color:Color(0x26000000), offset:Offset(5,12), blurRadius:24)]), child: const Column(mainAxisAlignment:MainAxisAlignment.center, children:[Text('Zatiaľ žiadny dokument.', style:TextStyle(color:blue,fontSize:28,fontWeight:FontWeight.w500)), SizedBox(height:19), Text('Podporované: PDF, DOCX, TXT (max. 10 MB)', style:TextStyle(color:blue,fontSize:24))])) : FigmaCard(width:935,height:285, child:ListView(children:items.map((e)=>ListTile(title:Text(e['title']??'',style:const TextStyle(color:Colors.black,fontSize:16)), trailing:IconButton(icon:const Icon(Icons.delete_outline,color:blue), onPressed:()async{await api.delete('/api/materials/${e['id']}'); await load();}))).toList()))])));}
